{

"kind": "propose",
"summary": "Adjust liveness probe timeout and initial delay to match observed startup duration",
"hypotheses": [
  {
    "root_cause_class": "probe_too_strict_for_startup",
    "summary": "Liveness probe kills app during startup due to insufficient timeout and delay",
    "supporting": ["probe_kills", "killed_during_startup", "ev-container_logs_tail"],
    "contradicting": ["probe_timeouts"],
    "missing": [],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-probes",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "finance",
    "name": "ledger",
    "uid": "uid-deployment-ledger"
  },
  "params": {
    "container": "app",
    "liveness": {
      "initialDelaySeconds": 20,
      "timeoutSeconds": 5
    }
  },
  "expected_effect": "Prevent liveness probe from killing the app during startup",
  "rationale": "Logs show the app was still initializing (loading 11.93M accounts) when the liveness probe failed. The 1s timeout is insufficient for the 32s startup duration. Increasing initialDelaySeconds to 20s allows the app to start, while timeoutSeconds=5s provides a buffer for slow responses.",
  "cited_evidence_ids": ["ev-rollout_history", "ev-pod_states", "ev-target_events", "ev-container_logs_tail"],
  "cited_predicates": ["killed_during_startup", "probe_kills"]
}
}
